import{z as c,x as A,o as r,c as i,q as E,j as l,D as t,d as a,s as d,S as s,b as o}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"控制器真值表","description":"","frontmatter":{"title":"控制器真值表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/control-truth-table.md","filePath":"cs/control-truth-table.md","lastUpdated":1791413859000}'),p={name:"cs/control-truth-table.md"};function B(u,e,m,h,f,D){const n=A("Mermaid");return r(),i("div",null,[e[2]||(e[2]=E('<h1 id="控制器真值表" tabindex="-1">控制器真值表 <a class="header-anchor" href="#控制器真值表" aria-label="Permalink to &quot;控制器真值表&quot;">​</a></h1><div class="epigraph"><p>数据通路上每根选择线都是 opcode 的组合函数；把指令类型排成表，综合成门或 ROM。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/single-cycle-datapath">单周期数据通路</a>把 ALUSrc、RegWrite、MemWrite 等留作端口。本课不重接 ALU 内部，也不从微程序另起。缺口是：<strong>谁根据指令比特驱动这些端口</strong>。答案是组合控制器：真值表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 每类指令需要一组确定的控制：<code>lw</code> 要 MemRead、MemtoReg、ALU 加、RegWrite；<code>sw</code> 要 MemWrite、ALU 加、不写堆；<code>beq</code> 要分支比较、不写堆；R 型要 ALU 功能来自 <code>funct</code>。缺口是把 <code>opcode</code>（及 <code>funct3</code>/<code>funct7</code>）映射到控制向量。ALU 控制可拆成主控给 <code>ALUOp</code>，再由第二张小表译 <code>funct</code>。</p><p>这是组合逻辑，延迟加在取指之后的关键路径上。无关 opcode 若必须 trap，行不能当 \\(X\\)。</p><p><span class="marginnote">「组合函数」就是输出只看当前输入、不记历史：opcode 一到，控制线立刻按表点亮，像自动售货机——按同一个键永远出同一罐，机器内部没有「上一次卖了什么」的记忆。单周期控制器正因如此用一张真值表就能写完，不需要状态机。</span></p><h3 id="真值表不是-fsm" tabindex="-1">真值表不是 FSM <a class="header-anchor" href="#真值表不是-fsm" aria-label="Permalink to &quot;真值表不是 FSM&quot;">​</a></h3><p>单周期没有「执行阶段状态」：一拍做完，控制器无现态寄存器。把本课画成多圆圈状态图，会与下一课多周期抢层。分支「是否成立」是数据通路比较结果与控制里 Branch 信号相与，仍是同一拍组合。</p><p><span class="marginnote">Patterson/Hennessy 用两级 ALU 控制减少主表列数。Harris 把控制写成 HDL 的 <code>case (opcode)</code>。实现可以是 ROM，内容仍是本课的表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>列指令类型 × 控制信号。<code>ALUOp</code> 再进 ALU 控制表出「加/减/与/或/slt」。综合成两级门，满足建立。非法 opcode 输出「异常」线，本课可先接地，<a href="/cs/exception-interrupt-entry">异常课</a>再接。</p>',12)),(r(),l(s,null,{default:t(()=>[d(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%5B%22opcode%20%2F%20funct%22%5D%20--%3E%20MAIN%5B%22%E4%B8%BB%E6%8E%A7%E5%88%B6%E7%9C%9F%E5%80%BC%E8%A1%A8%22%5D%0A%20%20MAIN%20--%3E%20ALUC%5B%22ALU%20%E6%8E%A7%E5%88%B6%E5%B0%8F%E8%A1%A8%22%5D%0A%20%20MAIN%20--%3E%20DP%5B%22%E6%95%B0%E6%8D%AE%E9%80%9A%E8%B7%AF%E6%8E%A7%E5%88%B6%E7%BA%BF%22%5D%0A%20%20ALUC%20--%3E%20DP%0A%20%20DP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%9A%E5%91%A8%E6%9C%9F%E6%8B%86%E6%8B%8D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,[a("控制延迟与指令存储器输出直接相关：opcode 来得晚，控制就晚，往往不在 "),o("code",null,"lw"),a(" 的内存路径上成为最长，但仍须签核。单周期 CPI 仍为 1，只是 \\(T\\) 含控制。")],-1)),e[5]||(e[5]=o("p",null,[o("code",null,"jal"),a("/"),o("code",null,"jalr"),a(" 的控制容易漏：RegWrite=1、写回值是 PC+4、ALU 或加法器算目标。表要单独一行。")],-1)),(r(),l(s,null,{default:t(()=>[d(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LW%5B%22lw%3A%20%E8%AF%BB%E5%86%85%E5%AD%98%22%5D%20--%3E%20S1%5B%22%E7%82%B9%E4%BA%AE%20RegWrite%2BMemtoReg%2C%20ALU%20%E7%AE%97%E5%8A%A0%E6%B3%95%E5%9C%B0%E5%9D%80%22%5D%0A%20%20SW%5B%22sw%3A%20%E5%86%99%E5%86%85%E5%AD%98%22%5D%20--%3E%20S2%5B%22%E7%82%B9%E4%BA%AE%20MemWrite%2C%20%E4%B8%8D%E5%86%99%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20BEQ%5B%22beq%3A%20%E5%88%86%E6%94%AF%22%5D%20--%3E%20S3%5B%22%E6%AF%94%E8%BE%83%E7%BB%93%E6%9E%9C%E4%B8%8E%20Branch%20%E4%BF%A1%E5%8F%B7%E7%9B%B8%E4%B8%8E%22%5D%0A%20%20JAL%5B%22jal%3A%20%E8%B7%B3%E8%BD%AC%E5%B9%B6%E9%93%BE%E6%8E%A5%22%5D%20--%3E%20S4%5B%22%E5%86%99%E5%9B%9E%20PC%2B4%2C%20%E8%A1%A8%E4%B8%8A%E6%98%93%E6%BC%8F%E7%9A%84%E4%B8%80%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<p><span class="marginnote">数字实例：主表以 opcode（7 位）为行、控制信号为列，RV32I 常用指令只占十来行；若把 funct3/funct7 也编进主表，行数立刻膨胀。两级表（主表只给 ALUOp，小表再译 funct）等于把「几十行大表」换成「十来行大表加 8 行小表」，省下门数与延迟。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把流水线控制按级寄存。不引入微码地址。CSR 指令的控制后置。</p><p>后课默认：单周期控制是 opcode 的组合函数。下一课为缩短 \\(T\\) 把指令拆成多拍，控制变成 FSM。</p><p><span class="marginnote">常见误区：把本课的控制器画成一圈圈状态转移的 FSM 图。单周期一拍做完，没有现态寄存器，真值表足矣；控制真正「有状态、有拍次」是下一课多周期的事——现在画 FSM 会把两课的层抢混。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制信号 = 指令类型的真值表（可加 ALU 子表）。</li><li>单周期控制器无状态。</li><li>非法编码与 <code>jal</code> 回写是表上易漏的行。</li><li>出处：Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const _=c(p,[["render",B]]);export{S as __pageData,_ as default};
